    /// <summary>
    ///     Tests the EDuke32 command-line arguments for the Duke base game with standard mods.
    /// </summary>
    [Fact]
    public void DukeTest()
    {
        var mods = _dukeMods.StandardModsWithCons;

        EDuke32 eduke32 = new();

        var args = eduke32.GetStartGameArgs(_dukeGame, _dukeCamp, mods, [], true, true, 3);

        var expected = "" +
                       " -g \"enabled_mod.zip\"" +
                       " -mh \"ENABLED1.DEF\"" +
                       " -mh \"ENABLED2.DEF\"" +
                       " -mx \"ENABLED1.CON\"" +
                       " -mx \"ENABLED2.CON\"" +
                       " -g \"mod_incompatible_with_addon.zip\"" +
                       " -g \"incompatible_mod_with_compatible_version.zip\"" +
                       " -g \"dependent_mod.zip\"" +
                       " -g \"dependent_mod_with_compatible_version.zip\"" +
                       " -g \"feature_mod.zip\"" +
                       $" -j \"{Directory.GetCurrentDirectory()}\\Data\\Addons\\Duke3D\\Mods\"" +
                       " -j \"D:\\Games\\Duke3D\"" +
                       " -s3" +
                       " -quick" +
                       " -nosetup" +
                       " -usecwd" +
                       " -cachesize 262144" +
                       " -h \"a\"" +
                       "";

        CmdArgsAssert.Equal(expected, args);
    }

