    /// <summary>
    ///     Tests that <see cref="EDuke32.BeforeStart" /> does not throw when FileInfo is null.
    /// </summary>
    [Fact]
    public void BeforeStart_NullFileInfo_DoesNotThrow()
    {
        var tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
        Directory.CreateDirectory(tempDir);

        try
        {
            var game = new DukeGame
            {
                Duke64RomPath = null,
                DukeZHRomPath = null,
                DukeWTInstallPath = null,
                GameInstallFolder = tempDir,
                AddonsPaths = []
            };

            var camp = new DukeCampaign
            {
                AddonId = new("test-camp", null),
                Type = AddonTypeEnum.Official,
                Title = "Test",
                SupportedGame = new(GameEnum.Duke3D, null, null),
                FileInfo = null,
                GridImageHash = null,
                PreviewImageHash = null,
                Description = null,
                Author = null,
                ReleaseDate = null,
                MainDef = null,
                AdditionalDefs = null,
                MainCon = null,
                AdditionalCons = null,
                RTS = null,
                StartMap = null,
                DependentAddons = null,
                IncompatibleAddons = null,
                RequiredFeatures = null,
                Executables = null,
                Options = null
            };

            EDuke32 eduke32 = new();
            eduke32.BeforeStart(game, camp);
        }
        finally
        {
            if (Directory.Exists(tempDir))
            {
                Directory.Delete(tempDir, true);
            }
        }
    }

    /// <summary>
    ///     Tests that <see cref="EDuke32.BeforeStart" /> lazily creates the WTStopgap folder.
    /// </summary>
    [Fact]
    public void BeforeStart_CreatesWTStopgapFolder()
    {
        var stopgapFolder = Path.Combine(new EDuke32().InstallFolderPath, ClientConsts.WTStopgap);

        if (Directory.Exists(stopgapFolder))
        {
            Directory.Delete(stopgapFolder, true);
        }

        try
        {
            Assert.False(Directory.Exists(stopgapFolder));

            var game = new DukeGame
            {
                Duke64RomPath = null,
                DukeZHRomPath = null,
                DukeWTInstallPath = null,
                GameInstallFolder = Path.GetTempPath(),
                AddonsPaths = []
            };

            var camp = new DukeCampaign
            {
                AddonId = new("wt-test", null),
                Type = AddonTypeEnum.Official,
                Title = "WT Test",
                SupportedGame = new(GameEnum.Duke3D, null, null),
                FileInfo = null,
                GridImageHash = null,
                PreviewImageHash = null,
                Description = null,
                Author = null,
                ReleaseDate = null,
                MainDef = null,
                AdditionalDefs = null,
                MainCon = null,
                AdditionalCons = null,
                RTS = null,
                StartMap = null,
                DependentAddons = null,
                IncompatibleAddons = null,
                RequiredFeatures = null,
                Executables = null,
                Options = null
            };

            new EDuke32().BeforeStart(game, camp);

            Assert.True(Directory.Exists(stopgapFolder));
            Assert.True(Directory.GetFiles(stopgapFolder).Length > 0);
        }
        finally
        {
            if (Directory.Exists(stopgapFolder))
            {
                Directory.Delete(stopgapFolder, true);
            }
        }
    }
}
